#include <iostream>
#include <string>
using namespace std;

class AkunBank {
private:
    string pemilik;
    int saldo;

public:
    AkunBank(const string &p, int awal) : pemilik(p), saldo(awal) {
    }

    bool setor(int jumlah) {
        if (jumlah <= 0) {
            return false;
        }
        saldo += jumlah;
        return true;
    }

    bool tarik(int jumlah) {
        if (jumlah <= 0 || jumlah > saldo) {
            return false;
        }
        saldo -= jumlah;
        return true;
    }

    int lihatSaldo() const {
        return saldo;
    }

    string getPemilik() const {
        return pemilik;
    }
};

int main() {
    string nama, perintah;
    int awal;
    cin >> nama >> awal;
    AkunBank akun(nama, awal);
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        int jumlah;
        cin >> jumlah;
        auto berhasil = false;
        if (perintah == "setor") {
            berhasil = akun.setor(jumlah);
        } else {
            berhasil = akun.tarik(jumlah);
        }
        if (berhasil) {
            cout << "Saldo: " << akun.lihatSaldo() << endl;
        } else {
            cout << "Ditolak" << endl;
        }
    }
    cout << akun.getPemilik() << ": " << akun.lihatSaldo() << endl;
    return 0;
}

