class Warna {
private:
    int merah;
    int hijau;
    int biru;

    static int batasi(int v) {
        if (v < 0) {
            return 0;
        }
        if (v > 255) {
            return 255;
        }
        return v;
    }

    static string duaHeks(int v) {
        string digit = "0123456789ABCDEF";
        string hasil = "";
        hasil += digit[v / 16];
        hasil += digit[v % 16];
        return hasil;
    }

public:
    Warna(int r, int g, int b) : merah(batasi(r)), hijau(batasi(g)), biru(batasi(b)) {
    }

    string heks() const {
        return "#" + duaHeks(merah) + duaHeks(hijau) + duaHeks(biru);
    }
};

int main() {
    int r, g, b;
    cin >> r >> g >> b;
    Warna w(r, g, b);
    cout << w.heks() << endl;
    return 0;
}

