    static bool kuat(const string &s) {
        auto adaAngka = false;
        for (auto c : s) {
            if (c >= '0' && c <= '9') {
                adaAngka = true;
            }
        }
        return s.size() >= 8 && adaAngka;
    }

public:
    Akun(const string &awal) : sandi(awal) {
    }

    int ganti(const string &lama, const string &baru) {
        if (lama != sandi) {
            return 1;
        }
        if (!kuat(baru)) {
            return 2;
        }
        sandi = baru;
        return 0;
    }

    bool masuk(const string &tebakan) const {
        return tebakan == sandi;
    }
};

int main() {
