#include <iostream>
using namespace std;

class Pecahan {
private:
    int pembilang;
    int penyebut;

    void rapikan() {
        if (penyebut < 0) {
            pembilang = -pembilang;
            penyebut = -penyebut;
        }
        int a = pembilang;
        if (a < 0) {
            a = -a;
        }
        int b = penyebut;
        while (b != 0) {
            int sisa = a % b;
            a = b;
            b = sisa;
        }
        pembilang /= a;
        penyebut /= a;
    }

public:
    Pecahan(int a, int b) : pembilang(a), penyebut(b) {
        rapikan();
    }

    static bool sah(int penyebut) {
        return penyebut != 0;
    }

    Pecahan tambah(const Pecahan &lain) const {
        return Pecahan(pembilang * lain.penyebut + lain.pembilang * penyebut, penyebut * lain.penyebut);
    }

    void cetak() const {
        cout << pembilang << "/" << penyebut << endl;
    }
};

int main() {
    int n;
    cin >> n;
    Pecahan jumlah(0, 1);
    for (int k = 0; k < n; k++) {
        int a, b;
        cin >> a >> b;
        if (!Pecahan::sah(b)) {
            cout << "Dilewati" << endl;
        } else {
            jumlah = jumlah.tambah(Pecahan(a, b));
        }
    }
    jumlah.cetak();
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

class Gudang {
private:
    string nama[10];
    int stok[10];
    int banyak = 0;

    int cari(const string &n) const {
        for (int k = 0; k < banyak; k++) {
            if (nama[k] == n) {
                return k;
            }
        }
        return -1;
    }

public:
    bool masuk(const string &n, int jumlah) {
        if (jumlah <= 0) {
            return false;
        }
        auto k = cari(n);
        if (k < 0) {
            k = banyak;
            nama[k] = n;
            stok[k] = 0;
            banyak++;
        }
        stok[k] += jumlah;
        return true;
    }

    bool keluar(const string &n, int jumlah) {
        auto k = cari(n);
        if (k < 0 || jumlah <= 0 || jumlah > stok[k]) {
            return false;
        }
        stok[k] -= jumlah;
        return true;
    }

    void laporan() const {
        for (int k = 0; k < banyak; k++) {
            cout << nama[k] << ": " << stok[k] << endl;
        }
    }
};

int main() {
    Gudang gudang;
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        string nama;
        int jumlah;
        cin >> nama >> jumlah;
        auto berhasil = false;
        if (perintah == "masuk") {
            berhasil = gudang.masuk(nama, jumlah);
        } else {
            berhasil = gudang.keluar(nama, jumlah);
        }
        if (!berhasil) {
            cout << "Ditolak" << endl;
        }
    }
    gudang.laporan();
    return 0;
}

