#include <iostream>
#include <string>
using namespace std;

class AntreanTerbatas {
private:
    int data[5];
    int depan = 0;
    int banyak = 0;

public:
    bool penuh() const {
        return banyak == 5;
    }

    bool kosong() const {
        return banyak == 0;
    }

    int ukuran() const {
        return banyak;
    }

    bool masuk(int x) {
        if (penuh()) {
            return false;
        }
        data[(depan + banyak) % 5] = x;
        banyak++;
        return true;
    }

    bool keluar(int &x) {
        if (kosong()) {
            return false;
        }
        x = data[depan];
        depan = (depan + 1) % 5;
        banyak--;
        return true;
    }
};

int main() {
    AntreanTerbatas antre;
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        if (perintah == "masuk") {
            int x;
            cin >> x;
            if (!antre.masuk(x)) {
                cout << "Penuh" << endl;
            }
        } else {
            int x;
            if (antre.keluar(x)) {
                cout << x << endl;
            } else {
                cout << "Kosong" << endl;
            }
        }
    }
    cout << "Sisa: " << antre.ukuran() << endl;
    return 0;
}

