    LarikAman(int n) : data(new int[n]), ukuran(n) {
        for (int k = 0; k < n; k++) {
            data[k] = 0;
        }
    }

    LarikAman(const LarikAman &lain) : data(new int[lain.ukuran]), ukuran(lain.ukuran) {
        for (int k = 0; k < ukuran; k++) {
            data[k] = lain.data[k];
        }
    }

    LarikAman &operator=(const LarikAman &lain) {
        if (this != &lain) {
            delete[] data;
            ukuran = lain.ukuran;
            data = new int[ukuran];
            for (int k = 0; k < ukuran; k++) {
                data[k] = lain.data[k];
            }
        }
        return *this;
    }

    ~LarikAman() {
        delete[] data;
    }

    bool atur(int i, int x) {
        if (!sah(i)) {
            return false;
        }
        data[i] = x;
        return true;
    }

    bool ambil(int i, int &x) const {
        if (!sah(i)) {
            return false;
        }
        x = data[i];
        return true;
    }

