        auto baru = new int[n];
        for (int k = 0; k < n; k++) {
            if (k < ukuran) {
                baru[k] = data[k];
            } else {
                baru[k] = 0;
            }
        }
        delete[] data;
        data = baru;
        ukuran = n;
    }

    int panjang() const {
        return ukuran;
    }
