class Lift {
private:
    int lantai;
    int tertinggi;
    int arah = 1;
    int langkah = 0;
    bool diminta[21];

    bool adaDiArah() const {
        for (int l = lantai + arah; l >= 1 && l <= tertinggi; l += arah) {
            if (diminta[l]) {
                return true;
            }
        }
        return false;
    }

public:
    Lift(int n, int awal) : lantai(awal), tertinggi(n) {
        for (auto &d : diminta) {
            d = false;
        }
    }

    bool minta(int l) {
        if (l < 1 || l > tertinggi || l == lantai || diminta[l]) {
            return false;
        }
        diminta[l] = true;
        return true;
    }

    bool adaPermintaan() const {
        for (int l = 1; l <= tertinggi; l++) {
            if (diminta[l]) {
                return true;
            }
        }
        return false;
    }

    int maju() {
        if (!adaDiArah()) {
            arah = -arah;
        }
        lantai += arah;
        langkah++;
        if (diminta[lantai]) {
            diminta[lantai] = false;
            return lantai;
        }
        return 0;
    }

    int totalLangkah() const {
        return langkah;
    }
};

int main() {
    int n, awal, k;
    cin >> n >> awal;
    cin >> k;
    Lift lift(n, awal);
    for (int p = 0; p < k; p++) {
        int l;
        cin >> l;
        if (!lift.minta(l)) {
            cout << "Ditolak " << l << endl;
        }
    }
