#include <iostream>
#include <string>
using namespace std;

class CacheLru {
private:
    int kunci[3];
    int nilai[3];
    int terakhir[3];
    int banyak = 0;
    int jam = 0;

    int cari(int k) const {
        for (int p = 0; p < banyak; p++) {
            if (kunci[p] == k) {
                return p;
            }
        }
        return -1;
    }

    int tertua() const {
        auto t = 0;
        for (int p = 1; p < banyak; p++) {
            if (terakhir[p] < terakhir[t]) {
                t = p;
            }
        }
        return t;
    }

public:
    bool ambil(int k, int &v) {
        auto p = cari(k);
        if (p < 0) {
            return false;
        }
        jam++;
        terakhir[p] = jam;
        v = nilai[p];
        return true;
    }

    int taruh(int k, int v) {
        auto dibuang = 0;
        auto p = cari(k);
        if (p < 0) {
            if (banyak == 3) {
                p = tertua();
                dibuang = kunci[p];
            } else {
                p = banyak;
                banyak++;
            }
            kunci[p] = k;
        }
        jam++;
        terakhir[p] = jam;
        nilai[p] = v;
        return dibuang;
    }

    void cetak() const {
        cout << "Isi:";
        auto batas = jam + 1;
        for (int n = 0; n < banyak; n++) {
            auto pilih = -1;
            for (int p = 0; p < banyak; p++) {
                if (terakhir[p] < batas && (pilih < 0 || terakhir[p] > terakhir[pilih])) {
                    pilih = p;
                }
            }
            cout << " " << kunci[pilih] << "=" << nilai[pilih];
            batas = terakhir[pilih];
        }
        cout << endl;
    }
};

int main() {
    CacheLru cache;
    string perintah;
    while (cin >> perintah) {
        if (perintah == "selesai") {
            break;
        }
        if (perintah == "taruh") {
            int k, v;
            cin >> k >> v;
            auto dibuang = cache.taruh(k, v);
            if (dibuang > 0) {
                cout << "Buang " << dibuang << endl;
            }
        } else {
            int k, v;
            cin >> k;
            if (cache.ambil(k, v)) {
                cout << v << endl;
            } else {
                cout << "tidak ada" << endl;
            }
        }
    }
    cache.cetak();
    return 0;
}
